656	/****************************************************************************
657	 * Private Functions - DMA Descriptor Management
658	 ****************************************************************************/
659	
660	static int alloc_dma(struct sg2000_eth_priv_s *priv)
661	{
662	  int i;
663	
664	  priv->tx_desc = kmm_memalign(16, TX_RING_SIZE *
665	                                sizeof(struct sg2000_dma_desc_s));
666	  priv->rx_desc = kmm_memalign(16, RX_RING_SIZE *
667	                                sizeof(struct sg2000_dma_desc_s));
668	
669	  if (!priv->tx_desc || !priv->rx_desc)
670	    {
671	      return -ENOMEM;
672	    }
673	
674	  memset(priv->tx_desc, 0, TX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
675	  memset(priv->rx_desc, 0, RX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
676	
677	  /* For MMU-less or identity-mapped platforms, virtual address = physical.
678	   * TODO: For strict MMU kernel builds, use mm_virt_to_phys().
679	   */
680	
681	  priv->tx_desc_phys = (uint32_t)(uintptr_t)priv->tx_desc;
682	  priv->rx_desc_phys = (uint32_t)(uintptr_t)priv->rx_desc;
683	
684	  for (i = 0; i < TX_RING_SIZE; i++)
685	    {
686	      priv->tx_buf[i] = kmm_memalign(4, TX_BUF_SIZE);
687	      if (!priv->tx_buf[i])
688	        {
689	          return -ENOMEM;
690	        }
691	
692	      priv->tx_pkt[i] = NULL;
693	    }
694	
695	  for (i = 0; i < RX_RING_SIZE; i++)
696	    {
697	      priv->rx_buf[i] = kmm_memalign(4, RX_BUF_SIZE);
698	      if (!priv->rx_buf[i])
699	        {
700	          return -ENOMEM;
701	        }
702	    }
703	
704	  return 0;
705	}
706	
707	static void init_desc_and_dma(struct sg2000_eth_priv_s *priv)
708	{
709	  uintptr_t base = priv->gmac_base;
710	  uintptr_t dma = base + DMA_CHAN_BASE;
711	  int i;
712	
713	  /* Initialize TX descriptors */
714	
715	  for (i = 0; i < TX_RING_SIZE; i++)
716	    {
717	      priv->tx_desc[i].des0 = 0;
718	      priv->tx_desc[i].des2 = (uint32_t)(uintptr_t)priv->tx_buf[i];
719	      priv->tx_pkt[i] = NULL;
720	    }
721	
722	  /* Initialize RX descriptors: set OWN=1 (DMA owns them, can write) */
723	
724	  for (i = 0; i < RX_RING_SIZE; i++)
725	    {
726	      priv->rx_desc[i].des0 = DESC_OWN;
727	      priv->rx_desc[i].des1 = RX_BUF_SIZE;
728	      priv->rx_desc[i].des2 = (uint32_t)(uintptr_t)priv->rx_buf[i];
729	    }
730	
731	  priv->tx_cur = 0;
732	  priv->tx_dirty = 0;
733	  priv->rx_cur = 0;
734	
735	  /* Program DMA registers */
736	
737	  putreg32(DMA_SYS_DEFAULT, base + DMA_SYS_BUS_MODE);
738	  putreg32(TX_RING_SIZE - 1, dma + DMA_CHAN_TX_RING_LEN);
739	  putreg32(RX_RING_SIZE - 1, dma + DMA_CHAN_RX_RING_LEN);
740	  putreg32(priv->tx_desc_phys, dma + DMA_CHAN_TX_BASE_ADDR);
741	  putreg32(priv->rx_desc_phys, dma + DMA_CHAN_RX_BASE_ADDR);
742	  putreg32(DMA_INTR_DEFAULT_MASK, dma + DMA_CHAN_INTR_ENA);
743	}
744	
745	/****************************************************************************
746	 * Private Functions - MAC and DMA Control
747	 ****************************************************************************/
748	
749	static void set_mac_addr(uintptr_t gmac_base, const uint8_t *mac)
750	{
751	  uint32_t hi;
752	  uint32_t lo;
753	
754	  hi = (mac[5] << 8) | mac[4] | GMAC_HI_REG_AE;
755	  lo = (mac[3] << 24) | (mac[2] << 16) | (mac[1] << 8) | mac[0];
756	
757	  putreg32(hi, gmac_base + GMAC_ADDR_HIGH(0));
758	  putreg32(lo, gmac_base + GMAC_ADDR_LOW(0));
759	}
760	
761	static void start_mac_and_dma(struct sg2000_eth_priv_s *priv)
762	{
763	  uintptr_t gmac_base = priv->gmac_base;
764	  uintptr_t dma = gmac_base + DMA_CHAN_BASE;
765	  uint32_t v;
766	
767	  /* Configure MAC based on PHY negotiation results */
768	
769	  v = GMAC_CORE_INIT;
770	  if (priv->speed == 100)
771	    {
772	      v |= GMAC_CONFIG_FES;   /* 100M */
773	    }
774	
775	  if (priv->duplex)
776	    {
777	      v |= GMAC_CONFIG_DM;    /* Full duplex */
778	    }
779	
780	  putreg32(v, gmac_base + GMAC_CONFIG);
781	
782	  /* Packet filter: pass multicast + broadcast + unicast to us */
783	
784	  putreg32(GMAC_FILTER_HMC | GMAC_FILTER_PM | GMAC_FILTER_PR,
785	           gmac_base + GMAC_PACKET_FILTER);
786	
787	  /* Enable MAC interrupts */
788	
789	  putreg32(GMAC_INT_DEFAULT, gmac_base + GMAC_INT_EN);
790	
791	  /* Enable MAC TX and RX */
792	
793	  v = getreg32(gmac_base + GMAC_CONFIG);
794	  putreg32(v | GMAC_CONFIG_TE | GMAC_CONFIG_RE, gmac_base + GMAC_CONFIG);
795	
796	  /* Start TX DMA */
797	
798	  v = getreg32(dma + DMA_CHAN_TX_CONTROL);
799	  putreg32(v | DMA_TX_ST, dma + DMA_CHAN_TX_CONTROL);
800	
801	  /* Start RX DMA */
802	
803	  v = getreg32(dma + DMA_CHAN_RX_CONTROL);
804	  putreg32(v | DMA_RX_SR, dma + DMA_CHAN_RX_CONTROL);
805	}
806	
807	/****************************************************************************
808	 * Private Functions - Doorbell Helpers
809	 ****************************************************************************/
810	
811	static void tx_doorbell(struct sg2000_eth_priv_s *priv)
812	{
813	  uint32_t tail = priv->tx_desc_phys +
814	                  priv->tx_cur * sizeof(struct sg2000_dma_desc_s);
815	
816	  putreg32(tail, priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_END_ADDR);
817	}
818	
819	static void rx_doorbell(struct sg2000_eth_priv_s *priv)
820	{
821	  uint32_t tail = priv->rx_desc_phys +
822	                  priv->rx_cur * sizeof(struct sg2000_dma_desc_s);
823	
824	  putreg32(tail, priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_END_ADDR);
825	}
826	
827	/****************************************************************************
828	 * Private Functions - Hardware Transmit
829	 ****************************************************************************/
830	
831	static int hw_transmit(struct sg2000_eth_priv_s *priv,
832	                       const uint8_t *data, int len)
833	{
834	  unsigned int idx = priv->tx_cur;
835	  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
836	  irqstate_t flags;
837	
838	  /* Check if the ring is full */
839	
840	  if (desc->des0 & DESC_OWN)
841	    {
842	      return -EBUSY;
843	    }
844	
845	  /* Copy data to DMA TX buffer */
846	
847	  memcpy(priv->tx_buf[idx], data, len);
848	
849	  desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];
850	  desc->des1 = len;
851	
852	  /* OWN | First Segment | Last Segment | Interrupt on Completion */
853	
854	  desc->des0 = DESC_OWN | TX_DESC_FS | TX_DESC_LS | TX_DESC_IC |
855	               (len & RX_DESC_FL_MASK);
856	
857	  flags = up_irq_save();
858	  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);
859	
860	  /* Memory barrier: ensure descriptor is visible to DMA engine */
861	
862	  __asm__ volatile ("fence w,w" ::: "memory");
863	
864	  tx_doorbell(priv);
865	  up_irq_restore(flags);
866	
867	  return 0;
868	}
869	
870	/****************************************************************************
871	 * Private Functions - TX Cleanup (called from ISR on TX complete)
872	 ****************************************************************************/
873	
874	static void tx_cleanup(struct sg2000_eth_priv_s *priv)
875	{
876	  irqstate_t flags = up_irq_save();
877	
878	  while (priv->tx_dirty != priv->tx_cur)
879	    {
880	      struct sg2000_dma_desc_s *desc = &priv->tx_desc[priv->tx_dirty];
881	
882	      if (desc->des0 & DESC_OWN)
883	        {
884	          /* Still owned by DMA, stop */
885	
886	          break;
887	        }
888	
889	      /* Check for TX errors */
890	
891	      if (desc->des0 & TX_DESC_ES)
892	        {
893	          nerr("ERROR: TX error, status=0x%08" PRIX32 "\n", desc->des0);
894	        }
895	
896	      /* Free the netpkt if we have one tracked for this slot */
897	
898	      if (priv->tx_pkt[priv->tx_dirty] != NULL)
899	        {
900	          netpkt_free(&priv->dev, priv->tx_pkt[priv->tx_dirty], NETPKT_TX);
901	          priv->tx_pkt[priv->tx_dirty] = NULL;
902	
903	          /* Notify upper half that TX is done */
904	
905	          netdev_lower_txdone(&priv->dev);
906	        }
907	
908	      /* Move to next descriptor */
909	
910	      priv->tx_dirty = (priv->tx_dirty + 1) & (TX_RING_SIZE - 1);
911	    }
912	
913	  up_irq_restore(flags);
914	}
915	
916	/****************************************************************************
917	 * Private Functions - ISR
918	 ****************************************************************************/
919	
920	static int sg2000_eth_isr(int irq, void *context, void *arg)
921	{
922	  struct sg2000_eth_priv_s *priv = (struct sg2000_eth_priv_s *)arg;
923	  uintptr_t base = priv->gmac_base;
924	  uintptr_t dma = base + DMA_CHAN_BASE;
925	  uint32_t status;
926	  uint32_t intr_en;
927	  uint32_t mac;
928	
929	  /* Clear MAC interrupts */
930	
931	  mac = getreg32(base + GMAC_INT_STATUS);
932	  if (mac)
933	    {
934	      putreg32(mac, base + GMAC_INT_STATUS);
935	    }
936	
937	  /* Read DMA channel status (only enabled interrupts) */
938	
939	  intr_en = getreg32(dma + DMA_CHAN_INTR_ENA);
940	  status = getreg32(dma + DMA_CHAN_STATUS) & intr_en;
941	
942	  if (!status)
943	    {
944	      return OK;
945	    }
946	
947	  /* Write-1-to-clear the status bits */
948	
949	  putreg32(status, dma + DMA_CHAN_STATUS);
950	
951	  if (status & DMA_STATUS_NIS)
952	    {
953	      /* Normal interrupt */
954	
955	      if (status & DMA_STATUS_RI)
956	        {
957	          /* RX complete: notify upper half that packets are ready.
958	           * The upper half will call our receive() callback to get them.
959	           */
960	
961	          netdev_lower_rxready(&priv->dev);
962	        }
963	
964	      if (status & DMA_STATUS_TI)
965	        {
966	          /* TX complete: cleanup descriptors and notify upper half */
967	
968	          tx_cleanup(priv);
969	        }
970	    }
971	
972	  if (status & DMA_STATUS_AIS)
973	    {
974	      /* Abnormal interrupt */
975	
976	      nerr("ERROR: DMA Abnormal: 0x%08" PRIX32 "\n", status);
977	
978	      if (status & DMA_STATUS_RBU)
979	        {
980	          nerr("ERROR: RX Buffer Unavailable\n");
981	        }
982	
983	      if (status & DMA_STATUS_TPS)
984	        {
985	          nerr("ERROR: TX Process Stopped\n");
986	        }
987	
988	      if (status & DMA_STATUS_FBE)
989	        {
990	          nerr("ERROR: Fatal Bus Error\n");
991	        }
992	    }
993	
994	  return OK;
995	}
