997	/****************************************************************************
998	 * Name: netdriver_ifup
999	 *
1000	 * Description:
1001	 *   OpenVela netdev_ops_s ifup callback.  Starts the network device.
1002	 *
1003	 ****************************************************************************/
1004	
1005	static int netdriver_ifup(FAR struct netdev_lowerhalf_s *dev)
1006	{
1007	  FAR struct sg2000_eth_priv_s *priv =
1008	      (FAR struct sg2000_eth_priv_s *)dev;
1009	  int ret;
1010	
1011	  syslog(LOG_INFO, "sg2000_eth: ifup begin\n");
1012	
1013	  /* Ensure GMAC clocks and resets are configured */
1014	
1015	  gmac_clock_enable();
1016	
1017	  /* Set MAC core init (includes PS=MII mode) before PHY/MDIO operations. */
1018	
1019	  putreg32(GMAC_CORE_INIT, priv->gmac_base + GMAC_CONFIG);
1020	
1021	  ephy_hardware_reset(priv->phy_base, priv->phy_top);
1022	  up_mdelay(10);
1023	
1024	  ret = mdio_verify_phy(priv->gmac_base);
1025	  if (ret < 0)
1026	    {
1027	      nerr("ERROR: TRM legacy MDIO PHY not responding: %d\n", ret);
1028	      return ret;
1029	    }
1030	
1031	  syslog(LOG_INFO, "sg2000_eth: TRM legacy MDIO operational "
1032	         "mdio_addr=0x%08" PRIX32 " mdio_data=0x%08" PRIX32 "\n",
1033	         getreg32(priv->gmac_base + LEGACY_GMAC_MDIO_ADDR),
1034	         getreg32(priv->gmac_base + LEGACY_GMAC_MDIO_DATA));
1035	
1036	  ephy_full_tuning(priv->phy_base, priv->phy_top);
1037	
1038	  ret = phy_config_init(priv);
1039	  if (ret < 0)
1040	    {
1041	      nerr("ERROR: PHY init failed: %d\n", ret);
1042	      return ret;
1043	    }
1044	
1045	  ret = dma_soft_reset(priv->gmac_base);
1046	  if (ret < 0)
1047	    {
1048	      syslog(LOG_ERR, "sg2000_eth: DMA reset failed after PHY/MDIO "
1049	             "diagnostics: %d\n", ret);
1050	      return ret;
1051	    }
1052	
1053	  if (priv->tx_desc == NULL || priv->rx_desc == NULL)
1054	    {
1055	      ret = alloc_dma(priv);
1056	      if (ret < 0)
1057	        {
1058	          nerr("ERROR: alloc_dma failed: %d\n", ret);
1059	          return ret;
1060	        }
1061	    }
1062	
1063	  init_desc_and_dma(priv);
1064	  set_mac_addr(priv->gmac_base, priv->mac_addr);
1065	  start_mac_and_dma(priv);
1066	  rx_doorbell(priv);
1067	
1068	  up_enable_irq(priv->irq);
1069	  netdev_lower_carrier_on(dev);
1070	
1071	  syslog(LOG_INFO, "sg2000_eth: ifup done, %d Mbps %s duplex\n",
1072	         priv->speed, priv->duplex ? "Full" : "Half");
1073	
1074	  return OK;
1075	}
