1077	/****************************************************************************
1078	 * Name: netdriver_ifdown
1079	 *
1080	 * Description:
1081	 *   OpenVela netdev_ops_s ifdown callback.  Stops the network device.
1082	 *
1083	 ****************************************************************************/
1084	
1085	static int netdriver_ifdown(FAR struct netdev_lowerhalf_s *dev)
1086	{
1087	  FAR struct sg2000_eth_priv_s *priv =
1088	      (FAR struct sg2000_eth_priv_s *)dev;
1089	  uint32_t v;
1090	
1091	  up_disable_irq(priv->irq);
1092	
1093	  /* Stop TX DMA */
1094	
1095	  v = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL);
1096	  putreg32(v & ~DMA_TX_ST,
1097	           priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL);
1098	
1099	  /* Stop RX DMA */
1100	
1101	  v = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL);
1102	  putreg32(v & ~DMA_RX_SR,
1103	           priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL);
1104	
1105	  /* Disable MAC TX/RX */
1106	
1107	  v = getreg32(priv->gmac_base + GMAC_CONFIG);
1108	  putreg32(v & ~(GMAC_CONFIG_TE | GMAC_CONFIG_RE),
1109	           priv->gmac_base + GMAC_CONFIG);
1110	
1111	  netdev_lower_carrier_off(dev);
1112	
1113	  ninfo("netdriver_ifdown: interface down\n");
1114	
1115	  return OK;
1116	}
