1118	/****************************************************************************
1119	 * Name: netdriver_transmit
1120	 *
1121	 * Description:
1122	 *   OpenVela netdev_ops_s transmit callback.  Sends a packet.
1123	 *   The driver takes ownership of the netpkt and MUST free it after TX
1124	 *   completion (or on error).
1125	 *
1126	 *   Returned Value:
1127	 *     OK on success (pkt queued for TX); negated errno on failure.
1128	 *
1129	 ****************************************************************************/
1130	
1131	static int netdriver_transmit(FAR struct netdev_lowerhalf_s *dev,
1132	                               FAR netpkt_t *pkt)
1133	{
1134	  FAR struct sg2000_eth_priv_s *priv =
1135	      (FAR struct sg2000_eth_priv_s *)dev;
1136	  unsigned int len = netpkt_getdatalen(dev, pkt);
1137	  uint8_t tmp_buf[SG2000_ETH_BUFSIZE];
1138	  const uint8_t *data;
1139	  int ret;
1140	
1141	  if (len > SG2000_ETH_BUFSIZE)
1142	    {
1143	      nerr("ERROR: TX packet too large: %u\n", len);
1144	      netpkt_free(dev, pkt, NETPKT_TX);
1145	      return -E2BIG;
1146	    }
1147	
1148	  /* Extract data from netpkt.  If fragmented, copy out; else use pointer. */
1149	
1150	  if (netpkt_is_fragmented(pkt))
1151	    {
1152	      netpkt_copyout(dev, tmp_buf, pkt, len, 0);
1153	      data = tmp_buf;
1154	    }
1155	  else
1156	    {
1157	      data = netpkt_getdata(dev, pkt);
1158	      if (!data)
1159	        {
1160	          nerr("ERROR: netpkt_getdata returned NULL\n");
1161	          netpkt_free(dev, pkt, NETPKT_TX);
1162	          return -EINVAL;
1163	        }
1164	    }
1165	
1166	  /* Send via DMA */
1167	
1168	  ret = hw_transmit(priv, data, len);
1169	  if (ret < 0)
1170	    {
1171	      nerr("ERROR: hw_transmit failed: %d\n", ret);
1172	      netpkt_free(dev, pkt, NETPKT_TX);
1173	      return ret;
1174	    }
1175	
1176	  /* Track this packet: store it so tx_cleanup can free it after DMA done.
1177	   * The tx_cur was already advanced by hw_transmit, so use (tx_cur - 1).
1178	   */
1179	
1180	  {
1181	    irqstate_t flags = up_irq_save();
1182	    unsigned int slot = (priv->tx_cur - 1) & (TX_RING_SIZE - 1);
1183	
1184	    priv->tx_pkt[slot] = pkt;
1185	    up_irq_restore(flags);
1186	  }
1187	
1188	  return OK;
1189	}
1190	
1191	/****************************************************************************
1192	 * Name: netdriver_receive
1193	 *
1194	 * Description:
1195	 *   OpenVela netdev_ops_s receive callback.  Called by upper half when
1196	 *   netdev_lower_rxready() was signaled.  Returns one received packet, or
1197	 *   NULL if no more packets are available.
1198	 *
1199	 *   Returned Value:
1200	 *     A netpkt_t * containing the received packet, or NULL.
1201	 *
1202	 ****************************************************************************/
1203	
1204	static FAR netpkt_t *netdriver_receive(FAR struct netdev_lowerhalf_s *dev)
1205	{
1206	  FAR struct sg2000_eth_priv_s *priv =
1207	      (FAR struct sg2000_eth_priv_s *)dev;
1208	  FAR netpkt_t *pkt = NULL;
1209	  struct sg2000_dma_desc_s *desc;
1210	  uint32_t status;
1211	  int frame_len;
1212	  int ret;
1213	
1214	  /* Check if there is a completed RX descriptor */
1215	
1216	  desc = &priv->rx_desc[priv->rx_cur];
1217	  if (desc->des0 & DESC_OWN)
1218	    {
1219	      /* DMA still owns it, no packet ready yet.
1220	       * This can happen if rxready was signaled for a previous packet
1221	       * that was already consumed, or in edge cases.
1222	       */
1223	
1224	      return NULL;
1225	    }
1226	
1227	  status = desc->des0;
1228	
1229	  /* Check for errors */
1230	
1231	  if (status & RX_DESC_ES)
1232	    {
1233	      nerr("ERROR: RX error, status=0x%08" PRIX32 "\n", status);
1234	      goto refill;
1235	    }
1236	
1237	  /* Get frame length (includes FCS which we strip) */
1238	
1239	  frame_len = ((status >> RX_DESC_FL_SHIFT) & RX_DESC_FL_MASK) - ETH_FCSSLEN;
1240	
1241	  if (frame_len <= 0 || frame_len > CONFIG_NET_ETH_PKTSIZE)
1242	    {
1243	      nwarn("WARNING: Invalid RX frame length: %d\n", frame_len);
1244	      goto refill;
1245	    }
1246	
1247	  /* Allocate a netpkt for the received data */
1248	
1249	  pkt = netpkt_alloc(dev, NETPKT_RX);
1250	  if (!pkt)
1251	    {
1252	      nerr("ERROR: netpkt_alloc failed\n");
1253	      goto refill;
1254	    }
1255	
1256	  /* Copy data from DMA RX buffer into the netpkt */
1257	
1258	  ret = netpkt_copyin(dev, pkt, priv->rx_buf[priv->rx_cur], frame_len, 0);
1259	  if (ret < 0)
1260	    {
1261	      nerr("ERROR: netpkt_copyin failed: %d\n", ret);
1262	      netpkt_free(dev, pkt, NETPKT_RX);
1263	      goto refill;
1264	    }
1265	
1266	  ninfo("RX packet: %d bytes\n", frame_len);
1267	
1268	refill:
1269	  /* Return the descriptor to DMA (set OWN=1) */
1270	
1271	  desc->des0 = DESC_OWN;
1272	  desc->des1 = RX_BUF_SIZE;
1273	
1274	  priv->rx_cur = (priv->rx_cur + 1) & (RX_RING_SIZE - 1);
1275	  rx_doorbell(priv);
1276	
1277	  return pkt;
1278	}
