static int hw_transmit(struct sg2000_eth_priv_s *priv,
                       const uint8_t *data, int len)
{
  unsigned int idx = priv->tx_cur;
  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
  irqstate_t flags;

  /* Check if the ring is full */

  if (desc->des0 & DESC_OWN)
    {
      return -EBUSY;
    }

  /* Copy data to DMA TX buffer */

  memcpy(priv->tx_buf[idx], data, len);

  /* Write back the TX buffer so DMA can see the packet data.
   * Without this, the CPU's cache may hold dirty lines that the
   * non-coherent DMA engine cannot see.
   */

  dcache_clean_range((uintptr_t)priv->tx_buf[idx],
                     (uintptr_t)priv->tx_buf[idx] + len);

  desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];
  desc->des1 = len;

  /* OWN | First Segment | Last Segment | Interrupt on Completion */

  desc->des0 = DESC_OWN | TX_DESC_FS | TX_DESC_LS | TX_DESC_IC |
               (len & RX_DESC_FL_MASK);

  /* Write back the descriptor so DMA sees OWN=1 and the buffer address.
   * The fence ensures the stores are ordered before the doorbell write.
