static FAR netpkt_t *netdriver_receive(FAR struct netdev_lowerhalf_s *dev)
{
  FAR struct sg2000_eth_priv_s *priv =
      (FAR struct sg2000_eth_priv_s *)dev;
  FAR netpkt_t *pkt = NULL;
  struct sg2000_dma_desc_s *desc;
  uint32_t status;
  int frame_len;
  int ret;

  /* Check if there is a completed RX descriptor.
   * Invalidate the descriptor cache line first so we read the status
   * that DMA wrote back (OWN bit, frame length), not stale cached data.
   */

  desc = &priv->rx_desc[priv->rx_cur];
  dcache_invalidate_range((uintptr_t)desc,
                          (uintptr_t)desc +
                          sizeof(struct sg2000_dma_desc_s));

  if (desc->des0 & DESC_OWN)
    {
      /* DMA still owns it, no packet ready yet.
       * This can happen if rxready was signaled for a previous packet
       * that was already consumed, or in edge cases.
       */

      return NULL;
    }

  status = desc->des0;

  /* Check for errors */

  if (status & RX_DESC_ES)
    {
      nerr("ERROR: RX error, status=0x%08" PRIX32 "\n", status);
      goto refill;
    }

  /* Get frame length (includes FCS which we strip) */

  frame_len = ((status >> RX_DESC_FL_SHIFT) & RX_DESC_FL_MASK) - ETH_FCSSLEN;

  if (frame_len <= 0 || frame_len > CONFIG_NET_ETH_PKTSIZE)
    {
      nwarn("WARNING: Invalid RX frame length: %d\n", frame_len);
      goto refill;
    }

  /* Invalidate the RX data buffer so we read the data that DMA wrote,
   * not stale cached data from a previous use of this buffer.
   */

  dcache_invalidate_range((uintptr_t)priv->rx_buf[priv->rx_cur],
                          (uintptr_t)priv->rx_buf[priv->rx_cur] +
                          RX_BUF_SIZE);

  /* Allocate a netpkt for the received data */

  pkt = netpkt_alloc(dev, NETPKT_RX);
  if (!pkt)
    {
      nerr("ERROR: netpkt_alloc failed\n");
      goto refill;
    }

  /* Copy data from DMA RX buffer into the netpkt */

  ret = netpkt_copyin(dev, pkt, priv->rx_buf[priv->rx_cur], frame_len, 0);
  if (ret < 0)
    {
      nerr("ERROR: netpkt_copyin failed: %d\n", ret);
      netpkt_free(dev, pkt, NETPKT_RX);
      goto refill;
    }

  ninfo("RX packet: %d bytes\n", frame_len);

refill:
  /* Return the descriptor to DMA (set OWN=1).
   * Re-set the buffer address in des2 in case DMA overwrote it,
   * and flush the buffer to ensure clean state before DMA writes.
   */

  desc->des0 = DESC_OWN;
  desc->des1 = RX_BUF_SIZE;
  desc->des2 = (uint32_t)(uintptr_t)priv->rx_buf[priv->rx_cur];

  /* Flush the RX buffer before handing it back to DMA:
   * write back + invalidate so the buffer is clean for DMA to write into.
   */

  dcache_flush_range((uintptr_t)priv->rx_buf[priv->rx_cur],
                     (uintptr_t)priv->rx_buf[priv->rx_cur] + RX_BUF_SIZE);

  /* Write back the descriptor so DMA sees OWN=1 and the new buffer */

  dcache_clean_range((uintptr_t)desc,
                     (uintptr_t)desc + sizeof(struct sg2000_dma_desc_s));

  priv->rx_cur = (priv->rx_cur + 1) & (RX_RING_SIZE - 1);
  rx_doorbell(priv);

  return pkt;
}

