121	/****************************************************************************
122	 * Private Functions - D-Cache Operations (T-Head C906)
123	 *
124	 * The C906 has a 32KB 4-way set-associative D-Cache with 64-byte cache
125	 * lines using PIPT (Physical Index + Physical Tag).  DDR memory
126	 * (0x80000000-0xC0000000) is mapped as cacheable via MMU.  DMA
127	 * descriptors and buffers allocated from the kernel heap are therefore
128	 * cacheable, and explicit cache maintenance is REQUIRED before any DMA
129	 * engine access.
130	 *
131	 * The Synopsys DWMAC DMA engine is NOT cache-coherent on this SoC.
132	 *
133	 * T-Head custom instructions (from CV181x/SG2002 TRM):
134	 *   dcache.cpa  rs1  (0x0295000b)  – Clean (write back) by physical addr
135	 *   dcache.ipa  rs1  (0x02a5000b)  – Invalidate by physical addr
136	 *   dcache.cipa rs1  (0x02b5000b)  – Clean + Invalidate by physical addr
137	 *   sync.s           (0x0190000b)  – Memory sync barrier
138	 ****************************************************************************/
139	
140	static void dcache_clean_range(uintptr_t start, uintptr_t end)
141	{
142	  register uintptr_t i asm("a0") = start & ~(64 - 1);
143	
144	  for (; i < end; i += 64)
145	    {
146	      asm volatile (".long 0x0295000b" ::: "memory");  /* dcache.cpa a0 */
147	    }
148	
149	  asm volatile (".long 0x0190000b" ::: "memory");      /* sync.s */
150	}
151	
152	static void dcache_invalidate_range(uintptr_t start, uintptr_t end)
153	{
154	  register uintptr_t i asm("a0") = start & ~(64 - 1);
155	
156	  for (; i < end; i += 64)
157	    {
158	      asm volatile (".long 0x02a5000b" ::: "memory");  /* dcache.ipa a0 */
159	    }
160	
161	  asm volatile (".long 0x0190000b" ::: "memory");      /* sync.s */
162	}
163	
164	static void dcache_flush_range(uintptr_t start, uintptr_t end)
165	{
166	  register uintptr_t i asm("a0") = start & ~(64 - 1);
167	
168	  for (; i < end; i += 64)
169	    {
170	      asm volatile (".long 0x02b5000b" ::: "memory");  /* dcache.cipa a0 */
171	    }
172	
173	  asm volatile (".long 0x0190000b" ::: "memory");      /* sync.s */
174	}
