180	static void gmac_clock_enable(void)
181	{
182	  uint32_t reg;
183	
184	  /* Enable GMAC0 clocks: clk_500m_eth0 + clk_axi4_eth0 */
185	
186	  reg = getreg32(REG_CLK_EN_0);
187	  reg |= CLK_EN_ETH0_500M | CLK_EN_ETH0_AXI4;
188	  putreg32(reg, REG_CLK_EN_0);
189	
190	  /* Deassert clock-domain resets used by the CVITEK clock-reset
191	   * controller.  Do not confuse these IDs with the main reset-controller
192	   * IDs at 0x03003000.
193	   */
194	
195	  clk_reset_deassert(CLK_RST_500M_ETH0);
196	  clk_reset_deassert(CLK_RST_AXI_ETH0);
197	
198	  /* Release the main reset-controller lines for GMAC and internal EPHY.
199	   * The Linux CVITEK reset driver deasserts by setting the corresponding
200	   * bit in the reset bank.
201	   */
202	
203	  reset_assert(RST_ETH0);
204	  reset_assert(RST_ETHPHY);
205	  reset_assert(RST_ETHPHYRST_APB);
206	  up_udelay(10);
207	  reset_deassert(RST_ETHPHYRST_APB);
208	  reset_deassert(RST_ETHPHY);
209	  reset_deassert(RST_ETH0);
210	  up_udelay(10);
211	
212	  syslog(LOG_INFO, "sg2000_eth: GMAC clocks enabled, CLK_EN_0=0x%08" PRIX32
213	         " RESET0=0x%08" PRIX32 " RESET3=0x%08" PRIX32 "\n",
214	         getreg32(REG_CLK_EN_0), getreg32(REG_RESET_BANK(0)),
215	         getreg32(REG_RESET_BANK(3)));
216	}
