398	static void ephy_hardware_reset(uintptr_t phy_base, uintptr_t phy_top)
399	{
400	  uint32_t apb_id1;
401	  uint32_t apb_id2;
402	
403	  ephy_led_pinmux();
404	
405	  /* Minimal EPHY init sequence, matches Linux bm_eth_reset_phy() in
406	   * dwmac-cvitek.c and U-Boot cv181x_ephy_id_init() in board.c.
407	   * This ONLY releases resets and programs the PHY ID — it does NOT
408	   * run the full analog tuning sequence.  The full tuning (which
409	   * accesses internal pages and starts auto-negotiation) must run
410	   * AFTER the MDIO interface is confirmed operational, just as
411	   * Linux does in cv182xa_phy_config_init() -> config_init callback.
412	   */
413	
414	  /* Select APB interface to access EPHY registers */
415	
416	  putreg32(0x0001, phy_top + 0x4);
417	
418	  /* Release shutdown */
419	
420	  putreg32(0x0900, phy_top);
421	
422	  /* Release dig_rst_n — enables MII register access via APB */
423	
424	  putreg32(0x0904, phy_top);
425	
426	  /* Switch to Page 5 for ANA init */
427	
428	  putreg32(0x0500, phy_base + 0x7c);
429	
430	  /* ANA_PD (power-down release) */
431	
432	  putreg32(0x0c00, phy_base + 0x40);
433	
434	  /* ANA_EN */
435	
436	  putreg32(0x0c7e, phy_base + 0x40);
437	  up_mdelay(1);
438	
439	  /* Release ana_rst_n */
440	
441	  putreg32(0x0906, phy_top);
442	  putreg32(0x0500, phy_base + 0x7c);
443	
444	  /* Program PHY ID into EPHY registers (so MDIO can discover it) */
445	
446	  putreg32(0x0043, phy_base + 0x08);  /* PHY_ID_HIGH */
447	  putreg32(0x5649, phy_base + 0x0c);  /* PHY_ID_LOW */
448	
449	  apb_id1 = getreg32(phy_base + 0x08) & 0xffff;
450	  apb_id2 = getreg32(phy_base + 0x0c) & 0xffff;
451	  syslog(LOG_INFO, "sg2000_eth: EPHY APB PHYID=0x%04" PRIX32
452	         "%04" PRIX32 "\n", apb_id1, apb_id2);
453	
454	  /* Switch control to MDIO (GMAC) so the DWMAC4 MDIO controller can
455	   * discover and communicate with the PHY.
456	   */
457	
458	  putreg32(0x0000, phy_top + 0x4);
459	  up_mdelay(10);
460	
461	  syslog(LOG_INFO, "sg2000_eth: EPHY init done top=0x%08" PRIX32
462	         " sel=0x%08" PRIX32 "\n",
463	         getreg32(phy_top), getreg32(phy_top + 0x4));
464	}
465	
466	/****************************************************************************
467	 * Name: ephy_full_tuning
468	 *
469	 * Description:
470	 *   Run the full CV182XA analog tuning sequence via APB, then switch back
471	 *   to MDIO control.  Matches Linux cv182xa_phy_config_init().
472	 *   MUST be called AFTER MDIO is confirmed operational, as it accesses
473	 *   internal pages and starts auto-negotiation which can interfere with
474	 *   MDIO if run before the MDIO interface is active.
475	 *
476	 ****************************************************************************/
477	
478	static void ephy_full_tuning(uintptr_t phy_base, uintptr_t phy_top)
479	{
480	  /* ephy_full_analog_init expects APB mode; caller ensures MDIO is working
481	   * before we switch to APB for tuning.
482	   */
483	
484	  putreg32(0x0001, phy_top + 0x4);
485	  ephy_full_analog_init(phy_base, phy_top);
486	
487	  /* ephy_full_analog_init ends with:
488	   *   page 0 + autoneg start (0x090e) + force full-duplex
489	   * Switch control back to MDIO so the GMAC can manage the PHY.
490	   */
491	
492	  putreg32(0x0000, phy_top + 0x4);
493	  up_mdelay(10);
494	
495	  syslog(LOG_INFO, "sg2000_eth: EPHY full tuning done, top=0x%08" PRIX32
496	         " sel=0x%08" PRIX32 "\n",
497	         getreg32(phy_top), getreg32(phy_top + 0x4));
498	}
499	
500	/* SG2000/CV181x uses the TRM (Technical Reference Manual) Chapter 18
501	 * legacy GMAC MDIO layout at offsets 0x10/0x14.  The standard DWMAC4
502	 * MDIO controller at 0x200/0x204 is not functional on this silicon.
503	 */
504	
505	static uint16_t mdio_read(uintptr_t gmac_base, int phy_addr, int reg)
506	{
507	  uint32_t cmd;
508	  int timeout = 10000;
509	
510	  do
511	    {
512	      if (!(getreg32(gmac_base + LEGACY_GMAC_MDIO_ADDR) &
513	            LEGACY_GMAC_MDIO_BUSY))
514	        {
515	          break;
516	        }
517	
518	      up_udelay(1);
519	    }
520	  while (--timeout > 0);
521	
522	  if (timeout <= 0)
523	    {
524	      return 0xffff;
525	    }
526	
527	  putreg32(0, gmac_base + LEGACY_GMAC_MDIO_DATA);
528	
529	  cmd = (((uint32_t)phy_addr & 0x1f) << LEGACY_GMAC_MDIO_PHY_SHIFT) |
530	        (((uint32_t)reg & 0x1f) << LEGACY_GMAC_MDIO_REG_SHIFT) |
531	        LEGACY_GMAC_MDIO_CR_250_300M | LEGACY_GMAC_MDIO_BUSY;
532	  putreg32(cmd, gmac_base + LEGACY_GMAC_MDIO_ADDR);
533	
534	  timeout = 10000;
535	  do
536	    {
537	      if (!(getreg32(gmac_base + LEGACY_GMAC_MDIO_ADDR) &
538	            LEGACY_GMAC_MDIO_BUSY))
539	        {
540	          return getreg32(gmac_base + LEGACY_GMAC_MDIO_DATA) & 0xffff;
541	        }
542	
543	      up_udelay(1);
544	    }
545	  while (--timeout > 0);
546	
547	  return 0xffff;
548	}
549	
550	static void mdio_write(uintptr_t gmac_base, int phy_addr, int reg,
551	                       uint16_t data)
552	{
553	  uint32_t cmd;
554	  int timeout = 10000;
555	
556	  putreg32(data, gmac_base + LEGACY_GMAC_MDIO_DATA);
557	  cmd = (((uint32_t)phy_addr & 0x1f) << LEGACY_GMAC_MDIO_PHY_SHIFT) |
558	        (((uint32_t)reg & 0x1f) << LEGACY_GMAC_MDIO_REG_SHIFT) |
559	        LEGACY_GMAC_MDIO_CR_250_300M | LEGACY_GMAC_MDIO_WRITE |
560	        LEGACY_GMAC_MDIO_BUSY;
561	  putreg32(cmd, gmac_base + LEGACY_GMAC_MDIO_ADDR);
562	
563	  do
564	    {
565	      if (!(getreg32(gmac_base + LEGACY_GMAC_MDIO_ADDR) &
566	            LEGACY_GMAC_MDIO_BUSY))
567	        {
568	          break;
569	        }
570	
571	      up_udelay(1);
572	    }
573	  while (--timeout > 0);
574	}
575	
576	static int mdio_verify_phy(uintptr_t gmac_base)
577	{
578	  uint16_t id1 = mdio_read(gmac_base, 0, 2);
579	  uint16_t id2 = mdio_read(gmac_base, 0, 3);
580	  uint32_t phy_id = ((uint32_t)id1 << 16) | id2;
581	
582	  syslog(LOG_INFO, "sg2000_eth: TRM legacy MDIO probe phy_id=0x%08"
583	         PRIX32 "\n", phy_id);
584	
585	  if (id1 == 0xffff || id2 == 0xffff)
586	    {
587	      syslog(LOG_ERR, "sg2000_eth: TRM legacy MDIO timeout reading "
588	             "PHY ID\n");
589	      return -ENODEV;
590	    }
591	
592	  if (phy_id != CVITEK_PHY_ID)
593	    {
594	      syslog(LOG_WARNING, "sg2000_eth: unexpected PHY ID 0x%08" PRIX32
595	             " (expected 0x%08" PRIX32 ")\n", phy_id,
596	             (uint32_t)CVITEK_PHY_ID);
597	    }
598	
599	  return OK;
600	}
