602	/****************************************************************************
603	 * Private Functions - PHY Configuration
604	 ****************************************************************************/
605	
606	static int phy_config_init(struct sg2000_eth_priv_s *priv)
607	{
608	  uint16_t bmsr;
609	  uint16_t bmcr;
610	  uint16_t anlpar;
611	  int timeout;
612	  uint16_t id1 = mdio_read(priv->gmac_base, 0, 2);
613	  uint16_t id2 = mdio_read(priv->gmac_base, 0, 3);
614	  uint32_t phy_id = (id1 << 16) | id2;
615	
616	  syslog(LOG_INFO, "sg2000_eth: PHY ID=0x%08" PRIX32
617	         " expect=0x00435649\n", phy_id);
618	
619	  if (phy_id == 0xffffffff)
620	    {
621	      syslog(LOG_ERR, "sg2000_eth: PHY not responding\n");
622	      return -1;
623	    }
624	
625	  if (phy_id != CVITEK_PHY_ID)
626	    {
627	      syslog(LOG_WARNING, "sg2000_eth: unexpected PHY ID 0x%08" PRIX32
628	             "\n", phy_id);
629	    }
630	
631	  priv->speed = 100;
632	  priv->duplex = 1;
633	
634	  mdio_write(priv->gmac_base, 0, 0, 0x8000);
635	  up_mdelay(10);
636	
637	  timeout = 100;
638	  do
639	    {
640	      bmcr = mdio_read(priv->gmac_base, 0, 0);
641	      if (!(bmcr & 0x8000))
642	        {
643	          break;
644	        }
645	
646	      up_mdelay(1);
647	    }
648	  while (--timeout > 0);
649	
650	  syslog(LOG_INFO, "sg2000_eth: PHY reset done, BMCR=0x%04X\n", bmcr);
651	
652	  mdio_write(priv->gmac_base, 0, 4, 0x01e1);
653	
654	  bmcr = mdio_read(priv->gmac_base, 0, 0);
655	  mdio_write(priv->gmac_base, 0, 0, bmcr | 0x1200);
656	  syslog(LOG_INFO, "sg2000_eth: autoneg start, BMCR=0x%04X\n",
657	         bmcr | 0x1200);
658	
659	  timeout = 50;
660	  do
661	    {
662	      (void)mdio_read(priv->gmac_base, 0, 1);
663	      bmsr = mdio_read(priv->gmac_base, 0, 1);
664	      if ((bmsr & 0x0004) != 0)
665	        {
666	          break;
667	        }
668	
669	      up_mdelay(100);
670	    }
671	  while (--timeout > 0);
672	
673	  if ((bmsr & 0x0004) == 0)
674	    {
675	      syslog(LOG_WARNING, "sg2000_eth: PHY link down, BMSR=0x%04X\n",
676	             bmsr);
677	      priv->link_up = 0;
678	      return OK;
679	    }
680	
681	  anlpar = mdio_read(priv->gmac_base, 0, 5);
682	  syslog(LOG_INFO, "sg2000_eth: PHY link detected, BMSR=0x%04X "
683	         "ANLPAR=0x%04X\n", bmsr, anlpar);
684	
685	  if ((anlpar & 0x0100) != 0)
686	    {
687	      priv->speed = 100;
688	      priv->duplex = 1;
689	    }
690	  else if ((anlpar & 0x0080) != 0)
691	    {
692	      priv->speed = 100;
693	      priv->duplex = 0;
694	    }
695	  else if ((anlpar & 0x0040) != 0)
696	    {
697	      priv->speed = 10;
698	      priv->duplex = 1;
699	    }
700	  else
701	    {
702	      priv->speed = 10;
703	      priv->duplex = 0;
704	    }
705	
706	  priv->link_up = 1;
707	
708	  return 0;
709	}
