711	/****************************************************************************
712	 * Private Functions - DMA Descriptor Management
713	 ****************************************************************************/
714	
715	static int alloc_dma(struct sg2000_eth_priv_s *priv)
716	{
717	  int i;
718	
719	  /* Descriptors and buffers MUST be aligned to the C906 cache-line
720	   * size (64 bytes, ARCH_DMA_MINALIGN) to prevent cache-line sharing
721	   * between adjacent descriptors/buffers, which would cause data
722	   * corruption when CPU and DMA write to different entities that
723	   * share the same cache line.
724	   */
725	
726	  priv->tx_desc = kmm_memalign(64, TX_RING_SIZE *
727	                                sizeof(struct sg2000_dma_desc_s));
728	  priv->rx_desc = kmm_memalign(64, RX_RING_SIZE *
729	                                sizeof(struct sg2000_dma_desc_s));
730	
731	  if (!priv->tx_desc || !priv->rx_desc)
732	    {
733	      return -ENOMEM;
734	    }
735	
736	  memset(priv->tx_desc, 0, TX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
737	  memset(priv->rx_desc, 0, RX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
738	
739	  /* For MMU-less or identity-mapped platforms, virtual address = physical.
740	   * TODO: For strict MMU kernel builds, use mm_virt_to_phys().
741	   */
742	
743	  priv->tx_desc_phys = (uint32_t)(uintptr_t)priv->tx_desc;
744	  priv->rx_desc_phys = (uint32_t)(uintptr_t)priv->rx_desc;
745	
746	  for (i = 0; i < TX_RING_SIZE; i++)
747	    {
748	      priv->tx_buf[i] = kmm_memalign(64, TX_BUF_SIZE);
749	      if (!priv->tx_buf[i])
750	        {
751	          return -ENOMEM;
752	        }
753	
754	      priv->tx_pkt[i] = NULL;
755	    }
756	
757	  for (i = 0; i < RX_RING_SIZE; i++)
758	    {
759	      priv->rx_buf[i] = kmm_memalign(64, RX_BUF_SIZE);
760	      if (!priv->rx_buf[i])
761	        {
762	          return -ENOMEM;
763	        }
764	    }
765	
766	  return 0;
767	}
768	
769	static void init_desc_and_dma(struct sg2000_eth_priv_s *priv)
770	{
771	  uintptr_t base = priv->gmac_base;
772	  uintptr_t dma = base + DMA_CHAN_BASE;
773	  int i;
774	
775	  /* Initialize TX descriptors */
776	
777	  for (i = 0; i < TX_RING_SIZE; i++)
778	    {
779	      priv->tx_desc[i].des0 = 0;
780	      priv->tx_desc[i].des1 = 0;
781	      priv->tx_desc[i].des2 = (uint32_t)(uintptr_t)priv->tx_buf[i];
782	      priv->tx_desc[i].des3 = 0;
783	      priv->tx_pkt[i] = NULL;
784	    }
785	
786	  /* Flush TX descriptor ring so DMA sees the initialized state */
787	
788	  dcache_clean_range((uintptr_t)priv->tx_desc,
789	                     (uintptr_t)(priv->tx_desc + TX_RING_SIZE));
790	
791	  /* Initialize RX descriptors: set OWN=1 (DMA owns them, can write).
792	   * In ring mode the DMA controller auto-wraps based on the ring length;
793	   * des3 is not used for chaining.
794	   */
795	
796	  for (i = 0; i < RX_RING_SIZE; i++)
797	    {
798	      priv->rx_desc[i].des0 = DESC_OWN;
799	      priv->rx_desc[i].des1 = RX_BUF_SIZE;
800	      priv->rx_desc[i].des2 = (uint32_t)(uintptr_t)priv->rx_buf[i];
801	      priv->rx_desc[i].des3 = 0;
802	    }
803	
804	  /* Flush RX descriptor ring and buffers: DMA will read descriptors
805	   * and write data into the buffers.  Write back the descriptors so
806	   * DMA sees OWN=1.  Also flush RX buffers to ensure any stale cache
807	   * lines are written back before DMA overwrites them.
808	   */
809	
810	  dcache_clean_range((uintptr_t)priv->rx_desc,
811	                     (uintptr_t)(priv->rx_desc + RX_RING_SIZE));
812	
813	  for (i = 0; i < RX_RING_SIZE; i++)
814	    {
815	      dcache_flush_range((uintptr_t)priv->rx_buf[i],
816	                         (uintptr_t)priv->rx_buf[i] + RX_BUF_SIZE);
817	    }
818	
819	  priv->tx_cur = 0;
820	  priv->tx_dirty = 0;
821	  priv->rx_cur = 0;
822	
823	  /* Program DMA registers */
824	
825	  putreg32(DMA_SYS_DEFAULT, base + DMA_SYS_BUS_MODE);
826	  putreg32(TX_RING_SIZE - 1, dma + DMA_CHAN_TX_RING_LEN);
827	  putreg32(RX_RING_SIZE - 1, dma + DMA_CHAN_RX_RING_LEN);
828	  putreg32(priv->tx_desc_phys, dma + DMA_CHAN_TX_BASE_ADDR);
829	  putreg32(priv->rx_desc_phys, dma + DMA_CHAN_RX_BASE_ADDR);
830	  putreg32(DMA_INTR_DEFAULT_MASK, dma + DMA_CHAN_INTR_ENA);
831	}
832	
833	/****************************************************************************
834	 * Private Functions - MAC and DMA Control
835	 ****************************************************************************/
836	
837	static void set_mac_addr(uintptr_t gmac_base, const uint8_t *mac)
838	{
839	  uint32_t hi;
840	  uint32_t lo;
841	
842	  hi = (mac[5] << 8) | mac[4] | GMAC_HI_REG_AE;
843	  lo = (mac[3] << 24) | (mac[2] << 16) | (mac[1] << 8) | mac[0];
844	
845	  putreg32(hi, gmac_base + GMAC_ADDR_HIGH(0));
846	  putreg32(lo, gmac_base + GMAC_ADDR_LOW(0));
847	}
848	
849	static void start_mac_and_dma(struct sg2000_eth_priv_s *priv)
850	{
851	  uintptr_t gmac_base = priv->gmac_base;
852	  uintptr_t dma = gmac_base + DMA_CHAN_BASE;
853	  uint32_t v;
854	
855	  /* Configure MAC based on PHY negotiation results */
856	
857	  v = GMAC_CORE_INIT;
858	  if (priv->speed == 100)
859	    {
860	      v |= GMAC_CONFIG_FES;   /* 100M */
861	    }
862	
863	  if (priv->duplex)
864	    {
865	      v |= GMAC_CONFIG_DM;    /* Full duplex */
866	    }
867	
868	  putreg32(v, gmac_base + GMAC_CONFIG);
869	
870	  /* Packet filter: pass multicast + broadcast + unicast to us */
871	
872	  putreg32(GMAC_FILTER_HMC | GMAC_FILTER_PM | GMAC_FILTER_PR,
873	           gmac_base + GMAC_PACKET_FILTER);
874	
875	  /* Enable MAC interrupts */
876	
877	  putreg32(GMAC_INT_DEFAULT, gmac_base + GMAC_INT_EN);
878	
879	  /* Enable MAC TX and RX */
880	
881	  v = getreg32(gmac_base + GMAC_CONFIG);
882	  putreg32(v | GMAC_CONFIG_TE | GMAC_CONFIG_RE, gmac_base + GMAC_CONFIG);
883	
884	  /* Start TX DMA */
885	
886	  v = getreg32(dma + DMA_CHAN_TX_CONTROL);
887	  putreg32(v | DMA_TX_ST, dma + DMA_CHAN_TX_CONTROL);
888	
889	  /* Start RX DMA */
890	
891	  v = getreg32(dma + DMA_CHAN_RX_CONTROL);
892	  putreg32(v | DMA_RX_SR, dma + DMA_CHAN_RX_CONTROL);
893	}
