895	/****************************************************************************
896	 * Private Functions - Doorbell Helpers
897	 ****************************************************************************/
898	
899	static void tx_doorbell(struct sg2000_eth_priv_s *priv)
900	{
901	  uint32_t tail = priv->tx_desc_phys +
902	                  priv->tx_cur * sizeof(struct sg2000_dma_desc_s);
903	
904	  putreg32(tail, priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_END_ADDR);
905	}
906	
907	static void rx_doorbell(struct sg2000_eth_priv_s *priv)
908	{
909	  uint32_t tail = priv->rx_desc_phys +
910	                  priv->rx_cur * sizeof(struct sg2000_dma_desc_s);
911	
912	  putreg32(tail, priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_END_ADDR);
913	}
