915	/****************************************************************************
916	 * Private Functions - Hardware Transmit
917	 ****************************************************************************/
918	
919	static int hw_transmit(struct sg2000_eth_priv_s *priv,
920	                       const uint8_t *data, int len)
921	{
922	  unsigned int idx = priv->tx_cur;
923	  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
924	  irqstate_t flags;
925	
926	  /* Check if the ring is full */
927	
928	  if (desc->des0 & DESC_OWN)
929	    {
930	      return -EBUSY;
931	    }
932	
933	  /* Copy data to DMA TX buffer */
934	
935	  memcpy(priv->tx_buf[idx], data, len);
936	
937	  /* Write back the TX buffer so DMA can see the packet data.
938	   * Without this, the CPU's cache may hold dirty lines that the
939	   * non-coherent DMA engine cannot see.
940	   */
941	
942	  dcache_clean_range((uintptr_t)priv->tx_buf[idx],
943	                     (uintptr_t)priv->tx_buf[idx] + len);
944	
945	  desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];
946	  desc->des1 = len;
947	
948	  /* OWN | First Segment | Last Segment | Interrupt on Completion */
949	
950	  desc->des0 = DESC_OWN | TX_DESC_FS | TX_DESC_LS | TX_DESC_IC |
951	               (len & RX_DESC_FL_MASK);
952	
953	  /* Write back the descriptor so DMA sees OWN=1 and the buffer address.
954	   * The fence ensures the stores are ordered before the doorbell write.
955	   */
956	
957	  dcache_clean_range((uintptr_t)desc,
958	                     (uintptr_t)desc + sizeof(struct sg2000_dma_desc_s));
959	  __asm__ volatile ("fence w,w" ::: "memory");
960	
961	  flags = up_irq_save();
962	  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);
963	  tx_doorbell(priv);
964	  up_irq_restore(flags);
965	
966	  return 0;
967	}
968	
969	/****************************************************************************
970	 * Private Functions - TX Cleanup (called from ISR on TX complete)
971	 ****************************************************************************/
972	
973	static void tx_cleanup(struct sg2000_eth_priv_s *priv)
974	{
975	  irqstate_t flags = up_irq_save();
976	
977	  while (priv->tx_dirty != priv->tx_cur)
978	    {
979	      struct sg2000_dma_desc_s *desc = &priv->tx_desc[priv->tx_dirty];
980	
981	      /* Invalidate the descriptor cache line so we read the status
982	       * that DMA wrote back, not stale cached data.
983	       */
984	
985	      dcache_invalidate_range((uintptr_t)desc,
986	                              (uintptr_t)desc +
987	                              sizeof(struct sg2000_dma_desc_s));
988	
989	      if (desc->des0 & DESC_OWN)
990	        {
991	          /* Still owned by DMA, stop */
992	
993	          break;
994	        }
995	
996	      /* Check for TX errors */
997	
998	      if (desc->des0 & TX_DESC_ES)
999	        {
1000	          nerr("ERROR: TX error, status=0x%08" PRIX32 "\n", desc->des0);
1001	        }
1002	
1003	      /* Free the netpkt if we have one tracked for this slot */
1004	
1005	      if (priv->tx_pkt[priv->tx_dirty] != NULL)
1006	        {
1007	          netpkt_free(&priv->dev, priv->tx_pkt[priv->tx_dirty], NETPKT_TX);
1008	          priv->tx_pkt[priv->tx_dirty] = NULL;
1009	
1010	          /* Notify upper half that TX is done */
1011	
1012	          netdev_lower_txdone(&priv->dev);
1013	        }
1014	
1015	      /* Release descriptor: clear des0 so it can be reused. */
1016	
1017	      desc->des0 = 0;
1018	
1019	      /* Write back the cleared descriptor so DMA doesn't see stale OWN */
1020	
1021	      dcache_clean_range((uintptr_t)desc,
1022	                         (uintptr_t)desc +
1023	                         sizeof(struct sg2000_dma_desc_s));
1024	
1025	      /* Move to next descriptor */
1026	
1027	      priv->tx_dirty = (priv->tx_dirty + 1) & (TX_RING_SIZE - 1);
1028	    }
1029	
1030	  up_irq_restore(flags);
1031	}
1032	
1033	/****************************************************************************
1034	 * Private Functions - ISR
1035	 ****************************************************************************/
1036	
1037	static int sg2000_eth_isr(int irq, void *context, void *arg)
1038	{
1039	  struct sg2000_eth_priv_s *priv = (struct sg2000_eth_priv_s *)arg;
1040	  uintptr_t base = priv->gmac_base;
1041	  uintptr_t dma = base + DMA_CHAN_BASE;
1042	  uint32_t status;
1043	  uint32_t intr_en;
1044	  uint32_t mac;
1045	
1046	  /* Clear MAC interrupts */
1047	
1048	  mac = getreg32(base + GMAC_INT_STATUS);
1049	  if (mac)
1050	    {
1051	      putreg32(mac, base + GMAC_INT_STATUS);
1052	    }
1053	
1054	  /* Read DMA channel status (only enabled interrupts) */
1055	
1056	  intr_en = getreg32(dma + DMA_CHAN_INTR_ENA);
1057	  status = getreg32(dma + DMA_CHAN_STATUS) & intr_en;
1058	
1059	  if (!status)
1060	    {
1061	      return OK;
1062	    }
1063	
1064	  /* Write-1-to-clear the status bits */
1065	
1066	  putreg32(status, dma + DMA_CHAN_STATUS);
1067	
1068	  if (status & DMA_STATUS_NIS)
1069	    {
1070	      /* Normal interrupt */
1071	
1072	      if (status & DMA_STATUS_RI)
1073	        {
1074	          /* RX complete: notify upper half that packets are ready.
1075	           * The upper half will call our receive() callback to get them.
1076	           */
1077	
1078	          netdev_lower_rxready(&priv->dev);
1079	        }
1080	
1081	      if (status & DMA_STATUS_TI)
1082	        {
1083	          /* TX complete: cleanup descriptors and notify upper half */
1084	
1085	          tx_cleanup(priv);
1086	        }
1087	    }
1088	
1089	  if (status & DMA_STATUS_AIS)
1090	    {
1091	      /* Abnormal interrupt */
1092	
1093	      nerr("ERROR: DMA Abnormal: 0x%08" PRIX32 "\n", status);
1094	
1095	      if (status & DMA_STATUS_RBU)
1096	        {
1097	          nerr("ERROR: RX Buffer Unavailable\n");
1098	        }
1099	
1100	      if (status & DMA_STATUS_TPS)
1101	        {
1102	          nerr("ERROR: TX Process Stopped\n");
1103	        }
1104	
1105	      if (status & DMA_STATUS_FBE)
1106	        {
1107	          nerr("ERROR: Fatal Bus Error\n");
1108	        }
1109	    }
1110	
1111	  return OK;
1112	}
