1194	/****************************************************************************
1195	 * Name: netdriver_ifdown
1196	 *
1197	 * Description:
1198	 *   OpenVela netdev_ops_s ifdown callback.  Stops the network device.
1199	 *
1200	 ****************************************************************************/
1201	
1202	static int netdriver_ifdown(FAR struct netdev_lowerhalf_s *dev)
1203	{
1204	  FAR struct sg2000_eth_priv_s *priv =
1205	      (FAR struct sg2000_eth_priv_s *)dev;
1206	  uint32_t v;
1207	
1208	  up_disable_irq(priv->irq);
1209	
1210	  /* Stop TX DMA */
1211	
1212	  v = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL);
1213	  putreg32(v & ~DMA_TX_ST,
1214	           priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL);
1215	
1216	  /* Stop RX DMA */
1217	
1218	  v = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL);
1219	  putreg32(v & ~DMA_RX_SR,
1220	           priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL);
1221	
1222	  /* Disable MAC TX/RX */
1223	
1224	  v = getreg32(priv->gmac_base + GMAC_CONFIG);
1225	  putreg32(v & ~(GMAC_CONFIG_TE | GMAC_CONFIG_RE),
1226	           priv->gmac_base + GMAC_CONFIG);
1227	
1228	  netdev_lower_carrier_off(dev);
1229	
1230	  ninfo("netdriver_ifdown: interface down\n");
1231	
1232	  return OK;
1233	}
