1235	/****************************************************************************
1236	 * Name: netdriver_transmit
1237	 *
1238	 * Description:
1239	 *   OpenVela netdev_ops_s transmit callback.  Sends a packet.
1240	 *   The driver takes ownership of the netpkt and MUST free it after TX
1241	 *   completion (or on error).
1242	 *
1243	 *   Returned Value:
1244	 *     OK on success (pkt queued for TX); negated errno on failure.
1245	 *
1246	 ****************************************************************************/
1247	
1248	static int netdriver_transmit(FAR struct netdev_lowerhalf_s *dev,
1249	                               FAR netpkt_t *pkt)
1250	{
1251	  FAR struct sg2000_eth_priv_s *priv =
1252	      (FAR struct sg2000_eth_priv_s *)dev;
1253	  unsigned int len = netpkt_getdatalen(dev, pkt);
1254	  uint8_t tmp_buf[SG2000_ETH_BUFSIZE];
1255	  const uint8_t *data;
1256	  int ret;
1257	
1258	  if (len > SG2000_ETH_BUFSIZE)
1259	    {
1260	      nerr("ERROR: TX packet too large: %u\n", len);
1261	      netpkt_free(dev, pkt, NETPKT_TX);
1262	      return -E2BIG;
1263	    }
1264	
1265	  /* Extract data from netpkt.  If fragmented, copy out; else use pointer. */
1266	
1267	  if (netpkt_is_fragmented(pkt))
1268	    {
1269	      netpkt_copyout(dev, tmp_buf, pkt, len, 0);
1270	      data = tmp_buf;
1271	    }
1272	  else
1273	    {
1274	      data = netpkt_getdata(dev, pkt);
1275	      if (!data)
1276	        {
1277	          nerr("ERROR: netpkt_getdata returned NULL\n");
1278	          netpkt_free(dev, pkt, NETPKT_TX);
1279	          return -EINVAL;
1280	        }
1281	    }
1282	
1283	  /* Send via DMA */
1284	
1285	  ret = hw_transmit(priv, data, len);
1286	  if (ret < 0)
1287	    {
1288	      nerr("ERROR: hw_transmit failed: %d\n", ret);
1289	      netpkt_free(dev, pkt, NETPKT_TX);
1290	      return ret;
1291	    }
1292	
1293	  /* Track this packet: store it so tx_cleanup can free it after DMA done.
1294	   * The tx_cur was already advanced by hw_transmit, so use (tx_cur - 1).
1295	   */
1296	
1297	  {
1298	    irqstate_t flags = up_irq_save();
1299	    unsigned int slot = (priv->tx_cur - 1) & (TX_RING_SIZE - 1);
1300	
1301	    priv->tx_pkt[slot] = pkt;
1302	    up_irq_restore(flags);
1303	  }
1304	
1305	  return OK;
1306	}
