1308	/****************************************************************************
1309	 * Name: netdriver_receive
1310	 *
1311	 * Description:
1312	 *   OpenVela netdev_ops_s receive callback.  Called by upper half when
1313	 *   netdev_lower_rxready() was signaled.  Returns one received packet, or
1314	 *   NULL if no more packets are available.
1315	 *
1316	 *   Returned Value:
1317	 *     A netpkt_t * containing the received packet, or NULL.
1318	 *
1319	 ****************************************************************************/
1320	
1321	static FAR netpkt_t *netdriver_receive(FAR struct netdev_lowerhalf_s *dev)
1322	{
1323	  FAR struct sg2000_eth_priv_s *priv =
1324	      (FAR struct sg2000_eth_priv_s *)dev;
1325	  FAR netpkt_t *pkt = NULL;
1326	  struct sg2000_dma_desc_s *desc;
1327	  uint32_t status;
1328	  int frame_len;
1329	  int ret;
1330	
1331	  /* Check if there is a completed RX descriptor.
1332	   * Invalidate the descriptor cache line first so we read the status
1333	   * that DMA wrote back (OWN bit, frame length), not stale cached data.
1334	   */
1335	
1336	  desc = &priv->rx_desc[priv->rx_cur];
1337	  dcache_invalidate_range((uintptr_t)desc,
1338	                          (uintptr_t)desc +
1339	                          sizeof(struct sg2000_dma_desc_s));
1340	
1341	  if (desc->des0 & DESC_OWN)
1342	    {
1343	      /* DMA still owns it, no packet ready yet.
1344	       * This can happen if rxready was signaled for a previous packet
1345	       * that was already consumed, or in edge cases.
1346	       */
1347	
1348	      return NULL;
1349	    }
1350	
1351	  status = desc->des0;
1352	
1353	  /* Check for errors */
1354	
1355	  if (status & RX_DESC_ES)
1356	    {
1357	      nerr("ERROR: RX error, status=0x%08" PRIX32 "\n", status);
1358	      goto refill;
1359	    }
1360	
1361	  /* Get frame length (includes FCS which we strip) */
1362	
1363	  frame_len = ((status >> RX_DESC_FL_SHIFT) & RX_DESC_FL_MASK) - ETH_FCSSLEN;
1364	
1365	  if (frame_len <= 0 || frame_len > CONFIG_NET_ETH_PKTSIZE)
1366	    {
1367	      nwarn("WARNING: Invalid RX frame length: %d\n", frame_len);
1368	      goto refill;
1369	    }
1370	
1371	  /* Invalidate the RX data buffer so we read the data that DMA wrote,
1372	   * not stale cached data from a previous use of this buffer.
1373	   */
1374	
1375	  dcache_invalidate_range((uintptr_t)priv->rx_buf[priv->rx_cur],
1376	                          (uintptr_t)priv->rx_buf[priv->rx_cur] +
1377	                          RX_BUF_SIZE);
1378	
1379	  /* Allocate a netpkt for the received data */
1380	
1381	  pkt = netpkt_alloc(dev, NETPKT_RX);
1382	  if (!pkt)
1383	    {
1384	      nerr("ERROR: netpkt_alloc failed\n");
1385	      goto refill;
1386	    }
1387	
1388	  /* Copy data from DMA RX buffer into the netpkt */
1389	
1390	  ret = netpkt_copyin(dev, pkt, priv->rx_buf[priv->rx_cur], frame_len, 0);
1391	  if (ret < 0)
1392	    {
1393	      nerr("ERROR: netpkt_copyin failed: %d\n", ret);
1394	      netpkt_free(dev, pkt, NETPKT_RX);
1395	      goto refill;
1396	    }
1397	
1398	  ninfo("RX packet: %d bytes\n", frame_len);
1399	
1400	refill:
1401	  /* Return the descriptor to DMA (set OWN=1).
1402	   * Re-set the buffer address in des2 in case DMA overwrote it,
1403	   * and flush the buffer to ensure clean state before DMA writes.
1404	   */
1405	
1406	  desc->des0 = DESC_OWN;
1407	  desc->des1 = RX_BUF_SIZE;
1408	  desc->des2 = (uint32_t)(uintptr_t)priv->rx_buf[priv->rx_cur];
1409	
1410	  /* Flush the RX buffer before handing it back to DMA:
1411	   * write back + invalidate so the buffer is clean for DMA to write into.
1412	   */
1413	
1414	  dcache_flush_range((uintptr_t)priv->rx_buf[priv->rx_cur],
1415	                     (uintptr_t)priv->rx_buf[priv->rx_cur] + RX_BUF_SIZE);
1416	
1417	  /* Write back the descriptor so DMA sees OWN=1 and the new buffer */
1418	
1419	  dcache_clean_range((uintptr_t)desc,
1420	                     (uintptr_t)desc + sizeof(struct sg2000_dma_desc_s));
1421	
1422	  priv->rx_cur = (priv->rx_cur + 1) & (RX_RING_SIZE - 1);
1423	  rx_doorbell(priv);
1424	
1425	  return pkt;
1426	}
