1433	
1434	static const struct netdev_ops_s g_ops =
1435	{
1436	  netdriver_ifup,     /* ifup */
1437	  netdriver_ifdown,   /* ifdown */
1438	  netdriver_transmit, /* transmit */
1439	  netdriver_receive   /* receive */
