1450	/****************************************************************************
1451	 * Name: sg2000_eth_initialize
1452	 *
1453	 * Description:
1454	 *   Initialize the SG2000 Ethernet driver and register it with the OpenVela
1455	 *   network stack as a netdev_lowerhalf_s device.
1456	 *
1457	 *   Called from board_late_initialize() during system bringup.
1458	 *
1459	 ****************************************************************************/
1460	
1461	int sg2000_eth_initialize(void)
1462	{
1463	  FAR struct sg2000_eth_priv_s *priv = &g_eth_priv;
1464	  FAR struct netdev_lowerhalf_s *dev = &priv->dev;
1465	  int ret;
1466	
1467	  if (g_eth_initialized)
1468	    {
1469	      ninfo("SG2000 Ethernet driver already initialized\n");
1470	      return OK;
1471	    }
1472	
1473	  memset(priv, 0, sizeof(*priv));
1474	  priv->gmac_base = SG2000_GMAC_BASE;
1475	  priv->phy_base = SG2000_EPHY_BASE;
1476	  priv->phy_top = SG2000_EPHY_TOP;
1477	
1478	  /* Set a test MAC address (should be replaced with eFuse/OTP value) */
1479	
1480	  priv->mac_addr[0] = 0x02;
1481	  priv->mac_addr[1] = 0x00;
1482	  priv->mac_addr[2] = 0x00;
1483	  priv->mac_addr[3] = 0x00;
1484	  priv->mac_addr[4] = 0x00;
1485	  priv->mac_addr[5] = 0x01;
1486	
1487	  memcpy(dev->netdev.d_mac.ether.ether_addr_octet, priv->mac_addr,
1488	         IFHWADDRLEN);
1489	
1490	  dev->quota[NETPKT_TX] = TX_RING_SIZE / 2;
1491	  dev->quota[NETPKT_RX] = RX_RING_SIZE / 2;
1492	  dev->ops              = &g_ops;
1493	
1494	  priv->irq = SG2000_IRQ_GMAC;
1495	
1496	  ret = netdev_lower_register(dev, NET_LL_ETHERNET);
1497	  if (ret < 0)
1498	    {
1499	      nerr("ERROR: netdev_lower_register failed: %d\n", ret);
1500	      return ret;
1501	    }
1502	
1503	  netdev_lower_carrier_off(dev);
1504	  g_eth_initialized = true;
1505	  ninfo("SG2000 Ethernet driver registered as eth0 (lowerhalf)\n");
1506	
1507	  gmac_clock_enable();
1508	
1509	  ret = irq_attach(priv->irq, sg2000_eth_isr, priv);
1510	  if (ret < 0)
1511	    {
1512	      nerr("ERROR: irq_attach failed: %d\n", ret);
1513	      return OK;
1514	    }
1515	
1516	  up_enable_irq(priv->irq);
1517	  ninfo("IRQ %d enabled\n", priv->irq);
1518	
1519	  return OK;
1520	}
