23	MEMORY
24	{
25	    kflash (rx) : ORIGIN = 0x80200000, LENGTH = 2048K   /* w/ cache */
26	    ksram (rwx) : ORIGIN = 0x80400000, LENGTH = 2048K   /* w/ cache */
27	    pgram (rwx) : ORIGIN = 0x80600000, LENGTH = 4096K   /* w/ cache */
28	    ramdisk (rwx) : ORIGIN = 0x80A00000, LENGTH = 16M   /* w/ cache */
29	}
30	
31	OUTPUT_ARCH("riscv")
32	
33	/* Provide the kernel boundaries */
34	
35	__kflash_start = ORIGIN(kflash);
36	__kflash_size = LENGTH(kflash);
37	__ksram_start = ORIGIN(ksram);
38	__ksram_size = LENGTH(ksram);
39	__ksram_end = ORIGIN(ksram) + LENGTH(ksram);
40	
41	/* Page heap */
42	
43	__pgheap_start = ORIGIN(pgram);
44	__pgheap_size = LENGTH(pgram) + LENGTH(ramdisk);
45	
46	/* Application ramdisk */
47	
48	__ramdisk_start = ORIGIN(ramdisk);
49	__ramdisk_size = LENGTH(ramdisk);
50	__ramdisk_end  = ORIGIN(ramdisk) + LENGTH(ramdisk);
51	
52	SECTIONS
