static void init_desc_and_dma(struct sg2000_eth_priv_s *priv)
{
  uintptr_t base = priv->gmac_base;
  int i;
  int last;

  /* Program DMA Bus Mode register with operational parameters.
   * After dma_soft_reset() all bits are cleared; PBL (burst length)
   * MUST be programmed for DMA transfers to work.  Use PBL=8
   * matching the device tree snps,txpbl/snps,rxpbl settings.
   * ATDS=0 selects 16-byte descriptors.
   */

  putreg32(DMA_PBL_8 | DMA_FB | DMA_AAL, base + DMA_BUS_MODE);

  /* Initialize TX descriptors.  The last descriptor has TER (End of Ring)
   * set so DWMAC1000 wraps back to the ring base address.
   */

  last = TX_RING_SIZE - 1;
  for (i = 0; i < TX_RING_SIZE; i++)
    {
      priv->tx_desc[i].des0 = (i == last) ? TX_DESC_TER : 0;
      priv->tx_desc[i].des1 = 0;
      priv->tx_desc[i].des2 = (uint32_t)(uintptr_t)priv->tx_buf[i];
      priv->tx_desc[i].des3 = 0;
      priv->tx_pkt[i] = NULL;
    }

  /* Flush TX descriptor ring so DMA sees the initialized state */

  dcache_clean_range((uintptr_t)priv->tx_desc,
                     (uintptr_t)(priv->tx_desc + TX_RING_SIZE));

  /* Initialize RX descriptors: set OWN=1 (DMA owns them, can write).
   * The last descriptor has RER (End of Ring) set so DWMAC1000 wraps.
   */

  last = RX_RING_SIZE - 1;
  for (i = 0; i < RX_RING_SIZE; i++)
    {
      priv->rx_desc[i].des0 = DESC_OWN | ((i == last) ? RX_DESC_RER : 0);
      priv->rx_desc[i].des1 = RX_BUF_SIZE;
      priv->rx_desc[i].des2 = (uint32_t)(uintptr_t)priv->rx_buf[i];
      priv->rx_desc[i].des3 = 0;
    }

  /* Flush RX descriptor ring and buffers: DMA will read descriptors
   * and write data into the buffers.  Write back the descriptors so
   * DMA sees OWN=1.  Also flush RX buffers to ensure any stale cache
   * lines are written back before DMA overwrites them.
   */

  dcache_clean_range((uintptr_t)priv->rx_desc,
                     (uintptr_t)(priv->rx_desc + RX_RING_SIZE));

  for (i = 0; i < RX_RING_SIZE; i++)
    {
      dcache_flush_range((uintptr_t)priv->rx_buf[i],
                         (uintptr_t)priv->rx_buf[i] + RX_BUF_SIZE);
    }

  priv->tx_cur = 0;
  priv->tx_dirty = 0;
  priv->rx_cur = 0;

  /* Program DWMAC1000 flat DMA registers.
   * DWMAC1000 has NO ring-length registers; wrapping uses TER/RER bits.
   * DWMAC1000 has NO channel concept; all registers are flat at 0x1000+.
   */

  putreg32(priv->tx_desc_phys, base + DMA_TX_BASE_ADDR);
  putreg32(priv->rx_desc_phys, base + DMA_RCV_BASE_ADDR);
  putreg32(DMA_INTR_DEFAULT_MASK, base + DMA_INTR_ENA);
}

