static void start_mac_and_dma(struct sg2000_eth_priv_s *priv)
{
  uintptr_t gmac_base = priv->gmac_base;
  uint32_t v;

  /* Configure MAC based on PHY negotiation results */

  v = GMAC_CORE_INIT;
  if (priv->speed == 100)
    {
      v |= GMAC_CONFIG_FES;   /* 100M */
    }

  if (priv->duplex)
    {
      v |= GMAC_CONFIG_DM;    /* Full duplex */
    }

  putreg32(v, gmac_base + GMAC_CONFIG);

  /* Packet filter: pass multicast + broadcast + unicast to us */

  putreg32(GMAC_FILTER_HMC | GMAC_FILTER_PM | GMAC_FILTER_PR,
           gmac_base + GMAC_PACKET_FILTER);

  /* Clear any pending MAC interrupts */

  putreg32(0xffffffff, gmac_base + GMAC_INT_STATUS);

  /* Enable MAC interrupts */

  putreg32(GMAC_INT_DEFAULT, gmac_base + GMAC_INT_EN);

  /* Flush TX and RX FIFOs before enabling MAC/DMA */

  putreg32(0, gmac_base + 0x0048);  /* GMAC_TX_FLUSH */
  putreg32(0, gmac_base + 0x004c);  /* GMAC_RX_FLUSH */

  /* Enable MAC TX and RX */

  v = getreg32(gmac_base + GMAC_CONFIG);
  putreg32(v | GMAC_CONFIG_TE | GMAC_CONFIG_RE, gmac_base + GMAC_CONFIG);

  /* Start TX DMA via DWMAC1000 DMA_CONTROL (CSR6, 0x1018).
   * Bit 13 = ST (Start Transmit), Bit 0 = SR (Start Receive).
   * Start TX first; RX will be started after a short delay to avoid
   * race conditions where RX DMA tries to use descriptors before
   * the TX path is fully ready.
   */

  v = getreg32(gmac_base + DMA_CONTROL);
  putreg32(v | DMA_CONTROL_ST, gmac_base + DMA_CONTROL);
  up_udelay(10);

  v = getreg32(gmac_base + DMA_CONTROL);
  putreg32(v | DMA_CONTROL_SR, gmac_base + DMA_CONTROL);

  syslog(LOG_INFO, "sg2000_eth: DMA started "
         "bus_mode=0x%08" PRIX32 " dma_control=0x%08" PRIX32
         " dma_status=0x%08" PRIX32 " dma_intr=0x%08" PRIX32
         " tx_base=0x%08" PRIX32 " rx_base=0x%08" PRIX32 "\n",
         getreg32(gmac_base + DMA_BUS_MODE),
         getreg32(gmac_base + DMA_CONTROL),
         getreg32(gmac_base + DMA_STATUS),
         getreg32(gmac_base + DMA_INTR_ENA),
         getreg32(gmac_base + DMA_TX_BASE_ADDR),
         getreg32(gmac_base + DMA_RCV_BASE_ADDR));
